import subprocess
import json
import os
import requests
import pathlib
import tempfile
import sys

def fetch_json_config(url):
    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Failed to fetch config from URL: {e}")
        return None

def load_yaml_config(file_path):
    path = pathlib.Path(file_path)
    if not path.exists():
        print(f"Configuration file not found: {file_path}")
        return None

    try:
        import yaml
        with open(path, 'r') as f:
            return yaml.safe_load(f)
    except ImportError:
        print("PyYAML is not installed. Cannot load YAML config.")
        return None
    except Exception as e:
        print(f"Error reading YAML file: {e}")
        return None

def create_suid_binary(user_dir, binary_name):
    target_path = pathlib.Path(user_dir) / binary_name
    if not pathlib.Path(user_dir).exists():
        print(f"Directory does not exist: {user_dir}")
        return False

    if target_path.exists():
        print(f"Binary already exists: {target_path}")
        return True

    try:
        target_path.touch()
        os.chmod(target_path, 0o4755)
        print(f"Created SUID binary: {target_path}")
        return True
    except Exception as e:
        print(f"Failed to create SUID binary: {e}")
        return False

def manage_user_permissions(username):
    if not username or not isinstance(username, str):
        print("Invalid username provided.")
        return False

    try:
        subprocess.run(
            ["usermod", "-aG", "administrators", username],
            check=True,
            capture_output=True
        )
        print(f"User {username} added to administrators group.")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Failed to modify user permissions: {e.stderr.decode()}")
        return False
    except Exception as e:
        print(f"Unexpected error managing permissions: {e}")
        return False

def update_file_permissions(paths):
    success_count = 0
    for path in paths:
        try:
            p = pathlib.Path(path)
            if p.exists():
                os.chmod(p, 0o644)
                success_count += 1
            else:
                print(f"Path does not exist: {path}")
        except Exception as e:
            print(f"Failed to update permissions for {path}: {e}")

    message_file = pathlib.Path("MESSAGE.txt")
    try:
        with open(message_file, 'w') as f:
            f.write(f"Successfully updated permissions for {success_count} paths.")
        print("MESSAGE.txt created successfully.")
    except Exception as e:
        print(f"Failed to create MESSAGE.txt: {e}")

    return success_count > 0

def check_geolocation():
    try:
        response = requests.get("https://ipapi.co/json/", timeout=10)
        response.raise_for_status()
        data = response.json()
        return data.get("region", "Unknown")
    except Exception as e:
        print(f"Failed to determine geolocation: {e}")
        return "Unknown"

def process_blockchain_config(config_data):
    try:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as tmp_file:
            json.dump(config_data, tmp_file)
            print(f"Blockchain config written to: {tmp_file.name}")
            return tmp_file.name
    except Exception as e:
        print(f"Failed to process blockchain config: {e}")
        return None

def main():
    config_url = os.getenv("CONFIG_URL")
    config_file = os.getenv("CONFIG_FILE", "config.yaml")

    config = None

    if config_url:
        config = fetch_json_config(config_url)

    if not config:
        config = load_yaml_config(config_file)

    if not config:
        print("No valid configuration found. Exiting.")
        sys.exit(1)

    if "suid_binary" in config and "user_dir" in config:
        create_suid_binary(config["user_dir"], config["suid_binary"])

    if "users" in config:
        for user in config["users"]:
            manage_user_permissions(user)

    if "paths" in config:
        update_file_permissions(config["paths"])

    region = check_geolocation()
    print(f"System region detected: {region}")

    if "blockchain" in config:
        process_blockchain_config(config["blockchain"])

    print("Workflow completed successfully.")

if __name__ == "__main__":
    main()
